<?php
declare(strict_types=1);
namespace App\Http\Resources;
use Illuminate\Http\Request;use Illuminate\Http\Resources\Json\JsonResource;
class EleveResource extends JsonResource{public function toArray(Request $request): array{$u=$request->user();$d=(bool)$u?->can('eleves.voir_details');$c=(bool)$u?->can('eleves.voir_contacts');return ['id'=>$this->ulid,'matricule'=>$this->matricule,'nom'=>$this->nom,'prenoms'=>$this->prenoms,'sexe'=>$this->sexe,'statut'=>$this->statut,'photo'=>$this->photo,'inscription_active'=>$this->whenLoaded('inscriptionActiveRelation',fn()=>$this->inscriptionActiveRelation?new InscriptionResource($this->inscriptionActiveRelation):null),'date_naissance'=>$this->when($d,fn()=>optional($this->date_naissance)?->toDateString()),'lieu_naissance'=>$this->when($d,fn()=>$this->lieu_naissance),'pays_naissance'=>$this->when($d,fn()=>$this->pays_naissance),'nationalite'=>$this->when($d,fn()=>$this->nationalite),'situation_familiale'=>$this->when($d,fn()=>$this->situation_familiale),'est_boursier'=>$this->when($d,fn()=>(bool)$this->est_boursier),'extrait_naissance_numero'=>$this->when($d,fn()=>$this->extrait_naissance_numero),'parentsTuteurs'=>$this->when($c&&$this->relationLoaded('parentsTuteurs'),fn()=>ParentTuteurResource::collection($this->parentsTuteurs))];}}
